test("readable source titles survive parsing and lossless format conversion", () => {
	const markdown = `---\nid: business\ntitle: 业务入口\nsummary: 读者入口\nsources:\n  - id: trial\n    title: 试运行验证记录\n    repoId: project\n    path: docs/validation/trial.md\n---\n# 业务入口\n`;
	assert.equal(parseDocument(markdown, "docs/repo-wiki/业务.md").sources[0].title, "试运行验证记录");
	assert.equal(parseDocument(formatWikiDocument(markdown, "docs/repo-wiki/业务.md"), "docs/repo-wiki/业务.md").sources[0].title, "试运行验证记录");
	assert.throws(() => parseDocument(markdown.replace("title: 试运行验证记录", "title: ''"), "docs/repo-wiki/业务.md"), /SOURCE_TITLE_INVALID/);
});
test("Markdown evidence has a readable view without widening ranges or reference access", async () => {
	const root = mkdtempSync(path.join(os.tmpdir(), "lumine-source-reading-"));
	let reader;
	const put = (file, value) => {
		mkdirSync(path.dirname(path.join(root, file)), { recursive: true });
		writeFileSync(path.join(root, file), value);
	};
	try {
		put(".lumine/root.json", JSON.stringify({
			schemaVersion: 2,
			kind: "lumine-root"
		}));
		put(".lumine/project.json", JSON.stringify({
			schemaVersion: 2,
			workflowVersion: 2,
			repositories: [{
				id: "root",
				path: "."
			}],
			wiki: { root: "docs/repo-wiki" }
		}));
		put("reader/index.html", "<html>Reader</html>");
		put("docs/design-docs/方案.md", "---\ntitle: 交付设计说明\n---\n# 交付设计说明\n\n[实现](../../src/delivery.ts#L1)\n\n[验证](../validation/check.md#limits)\n");
		put("docs/validation/check.md", "# Delivery check\n\n<a id=\"limits\"></a>\n## Limits\n\nNot deployed.");
		put("docs/validation/broken.md", "---\ntitle: [unterminated\n---\n# 原始资料\n");
		put("src/delivery.ts", "export const ready = true;\n// private line outside the registered range\n");
		put("docs/repo-wiki/入口.md", `---\nid: delivery\ntitle: 交付\nsummary: Current delivery.\nsources:\n  - id: design\n    repoId: root\n    path: docs/design-docs/方案.md\n  - id: design-excerpt\n    repoId: root\n    path: docs/design-docs/方案.md\n    startLine: 4\n    endLine: 7\n  - id: short\n    title: Validation excerpt\n    repoId: root\n    path: docs/validation/check.md\n    startLine: 6\n    endLine: 6\n  - id: code\n    title: 交付状态判定\n    repoId: root\n    path: src/delivery.ts\n    startLine: 1\n    endLine: 1\n  - id: broken\n    repoId: root\n    path: docs/validation/broken.md\n---\n# 交付\n`);
		reader = await serveWiki(root, {
			port: 0,
			assetsRoot: path.join(root, "reader")
		});
		const get = async (url) => {
			const response = await fetch(reader.url + url);
			assert.equal(response.status, 200);
			return response.json();
		};
		const source = await get("/api/source?document=delivery&id=design");
		assert.equal(source.title, "交付设计说明");
		assert.equal(source.markdown.referenceFrom, "delivery#source:design");
		assert.equal(source.markdown.path, "docs/design-docs/方案.md");
		assert.match(source.markdown.body, /^# 交付设计说明/);
		assert.doesNotMatch(source.markdown.body, /^---/);
		assert.ok(source.markdown.sections.length);
		assert.doesNotMatch(JSON.stringify(source), new RegExp(root));
		const excerpt = await get("/api/source?document=delivery&id=short");
		assert.equal(excerpt.title, "Validation excerpt", "keep the source language, independent of interface language");
		assert.equal(excerpt.text, "Not deployed.");
		assert.equal(excerpt.markdown, undefined, "a registered excerpt cannot become full Markdown");
		const malformed = await get("/api/source?document=delivery&id=broken");
		assert.equal(malformed.markdown, undefined);
		assert.match(malformed.text, /unterminated/);
		const link = (from, target) => "/api/reference?" + new URLSearchParams({
			from,
			target
		});
		const implementation = await get(link(source.markdown.referenceFrom, "../../src/delivery.ts#L1"));
		assert.equal(implementation.sourceId, "code");
		const validation = await get(link(source.markdown.referenceFrom, "../validation/check.md#limits"));
		assert.equal(validation.kind, "markdown");
		assert.equal(validation.fragment, "limits");
		const heading = source.markdown.sections[0].id;
		const sourceSection = await get(link(source.markdown.referenceFrom, `#${heading}`));
		assert.equal(sourceSection.kind, "markdown");
		assert.equal(sourceSection.referenceFrom, "delivery#source:design");
		assert.equal(sourceSection.fragment, heading);
		for (const [from, target] of [
			["delivery#source:short", "../../src/delivery.ts"],
			["delivery#source:unknown", "../../src/delivery.ts"],
			["delivery#source:design", "../../src/delivery.ts#L2"],
			["delivery#source:design", "../../.env.local"],
			["delivery#source:design", "https://example.com/"]
		]) assert.notEqual((await fetch(reader.url + link(from, target))).status, 200, `${from} -> ${target}`);
	} finally {
		await reader?.close();
		rmSync(root, {
			recursive: true,
			force: true
		});
	}
});

